const KEY_REGEX = /^[a-z0-9][a-z0-9_-]{1,79}$/;
const SUPPORTED_LOCALES = ["en", "zh", "ko", "ru", "hi"] as const;

@Injectable()
export class MarketplaceCategoryImportAdapter
  implements
    ImportAdapter<MarketplaceCategoryImportPayload, MarketplaceCategoryImportState>,
    OnModuleInit
{
  readonly type = "marketplace-categories";
  readonly supportedModes = ["upsert", "replace"] as const;

  constructor(
    private readonly prisma: PrismaService,
    private readonly codes: CodesService,
    private readonly importRegistry: ImportRegistry,
  ) {}

  onModuleInit(): void {
    this.importRegistry.register(this);
  }

  getSchema(): ImportWorkbookSchema {
    return {
      sheets: [
        {
          name: "categories",
          required: true,
          columns: [
            {
              key: "category_key",
              header: "Mã danh mục",
              aliases: ["category_key", "mã danh mục", "category key", "key"],
              required: true,
              type: "string",
              example: "food_beverage",
            },
            {
              key: "name_vi",
              header: "Tên tiếng Việt",
              aliases: [
                "name_vi",
                "tên danh mục",
                "tên tiếng việt",
                "name vi",
                "tên danh mục (tiếng việt)",
              ],
              required: true,
              type: "string",
              maxLength: 120,
            },
            {
              key: "sort_order",
              header: "Thứ tự",
              aliases: ["sort_order", "thứ tự", "sort order", "thứ tự hiển thị"],
              type: "number",
              min: 0,
              defaultValue: 0,
            },
            {
              key: "status",
              header: "Trạng thái",
              aliases: ["status", "trạng thái"],
              type: "enum",
              enumValues: ["ACTIVE", "DISABLED"],
              defaultValue: "ACTIVE",
            },
            {
              key: "name_en",
              header: "Tên tiếng Anh",
              aliases: ["name_en", "tên tiếng anh", "name en", "english"],
              type: "string",
              maxLength: 120,
            },
            {
              key: "name_zh",
              header: "Tên tiếng Trung",
              aliases: ["name_zh", "tên tiếng trung", "name zh", "chinese"],
              type: "string",
              maxLength: 120,
            },
            {
              key: "name_ko",
              header: "Tên tiếng Hàn",
              aliases: ["name_ko", "tên tiếng hàn", "name ko", "korean"],
              type: "string",
              maxLength: 120,
            },
            {
              key: "name_ru",
              header: "Tên tiếng Nga",
              aliases: ["name_ru", "tên tiếng nga", "name ru", "russian"],
              type: "string",
              maxLength: 120,
            },
            {
              key: "name_hi",
              header: "Tên tiếng Ấn",
              aliases: ["name_hi", "tên tiếng ấn", "name hi", "hindi"],
              type: "string",
              maxLength: 120,
            },
          ],
        },
      ],
    };
  }

  authorize(context: ImportContext): void {
    if (!context.actorUserId) {
      throw new UnauthorizedException("Yêu cầu mã người dùng thực hiện nhập dữ liệu");
    }
  }

  parse(workbook: ParsedImportWorkbook, _context: ImportContext): MarketplaceCategoryImportPayload {
    const sheet = workbook.sheets.find(
      (s) => s.name.toLowerCase() === "categories" || s.name === workbook.sheets[0]?.name,
    );
    if (!sheet) {
      return { categories: [] };
    }

    const rows: MarketplaceCategoryImportRow[] = [];

    for (const rawRow of sheet.rows) {
      const getVal = (aliases: string[]): string => {
        for (const [k, v] of Object.entries(rawRow.values)) {
          const normKey = k.trim().toLowerCase();
          if (aliases.some((a) => a.toLowerCase() === normKey)) {
            return this.text(v);
          }
        }
        return "";
      };

      const importKey = getVal(["category_key", "mã danh mục", "category key", "key"]);
      const nameVi = getVal([
        "name_vi",
        "tên danh mục",
        "tên tiếng việt",
        "name vi",
        "tên danh mục (tiếng việt)",
      ]);
      const sortOrderRaw = getVal(["sort_order", "thứ tự", "sort order", "thứ tự hiển thị"]);
      const statusRaw = getVal(["status", "trạng thái"]).toUpperCase();

      const sortOrder =
        sortOrderRaw !== "" && !isNaN(Number(sortOrderRaw))
          ? Math.max(0, parseInt(sortOrderRaw, 10))
          : 0;
      const isActive = statusRaw === "" ? true : statusRaw === "ACTIVE";

      const LOCALE_ALIASES: Record<string, string[]> = {
        en: ["name_en", "tên tiếng anh", "tên (tiếng anh)", "name en", "english", "english name"],
        zh: [
          "name_zh",
          "tên tiếng trung",
          "tên (tiếng trung)",
          "name zh",
          "chinese",
          "chinese name",
        ],
        ko: ["name_ko", "tên tiếng hàn", "tên (tiếng hàn)", "name ko", "korean", "korean name"],
        ru: ["name_ru", "tên tiếng nga", "tên (tiếng nga)", "name ru", "russian", "russian name"],
        hi: [
          "name_hi",
          "tên tiếng ấn",
          "tên tiếng ấn độ",
          "tên (tiếng ấn độ)",
          "tên (tiếng ấn)",
          "name hi",
          "hindi",
          "hindi name",
        ],
      };

      const translations: Record<string, string> = {};
      for (const loc of SUPPORTED_LOCALES) {
        const val = getVal(LOCALE_ALIASES[loc]);
        if (val !== "") {
          translations[loc] = val;
        }
      }

      rows.push({
        rowNumber: rawRow.rowNumber,
        importKey,
        nameVi,
        sortOrder,
        isActive,
        translations,
      });
    }

    return { categories: rows };
  }

  validate(
    payload: MarketplaceCategoryImportPayload,
    _context: ImportContext,
  ): ImportValidationIssue[] {
    const issues: ImportValidationIssue[] = [];
    const seenKeys = new Map<string, number>();

    for (const row of payload.categories) {
      const sheetName = "categories";

      if (!row.importKey) {
        issues.push({
          severity: "error",
          sheet: sheetName,
          row: row.rowNumber,
          column: "category_key",
          code: "REQUIRED_FIELD_MISSING",
          message: "Thiếu mã danh mục (category_key)",
          value: row.importKey,
        });
      } else if (!KEY_REGEX.test(row.importKey)) {
        issues.push({
          severity: "error",
          sheet: sheetName,
          row: row.rowNumber,
          column: "category_key",
          code: "INVALID_KEY_FORMAT",
          message:
            "Mã danh mục không hợp lệ (phải bắt đầu bằng chữ cái/số thường, 2-80 ký tự [a-z0-9_-])",
          value: row.importKey,
        });
      } else {
        const lowerKey = row.importKey.toLowerCase();
        const firstSeenRow = seenKeys.get(lowerKey);
        if (firstSeenRow !== undefined) {
          issues.push({
            severity: "error",
            sheet: sheetName,
            row: row.rowNumber,
            column: "category_key",
            code: "DUPLICATE_KEY",
            message: `Trùng lặp category_key '${row.importKey}' với dòng ${firstSeenRow}`,
            value: row.importKey,
          });
        } else {
          seenKeys.set(lowerKey, row.rowNumber);
        }
      }

      if (!row.nameVi) {
        issues.push({
          severity: "error",
          sheet: sheetName,
          row: row.rowNumber,
          column: "name_vi",
          code: "REQUIRED_FIELD_MISSING",
          message: "Thiếu tên tiếng Việt (name_vi)",
          value: row.nameVi,
        });
      } else if (row.nameVi.length > 120) {
        issues.push({
          severity: "error",
          sheet: sheetName,
          row: row.rowNumber,
          column: "name_vi",
          code: "MAX_LENGTH_EXCEEDED",
          message: "Tên tiếng Việt không được vượt quá 120 ký tự",
          value: row.nameVi,
        });
      }

      if (row.sortOrder < 0) {
        issues.push({
          severity: "error",
          sheet: sheetName,
          row: row.rowNumber,
          column: "sort_order",
          code: "INVALID_NUMBER",
          message: "Thứ tự hiển thị phải là số nguyên ≥ 0",
          value: row.sortOrder,
        });
      }

      for (const [loc, val] of Object.entries(row.translations)) {
        if (val && val.length > 120) {
          issues.push({
            severity: "error",
            sheet: sheetName,
            row: row.rowNumber,
            column: `name_${loc}`,
            code: "MAX_LENGTH_EXCEEDED",
            message: `Tên tiếng [${loc}] không được vượt quá 120 ký tự`,
            value: val,
          });
        }
      }
    }

    return issues;
  }

  async loadCurrentState(_context: ImportContext): Promise<MarketplaceCategoryImportState> {
    const categories = await this.prisma.marketplaceCategory.findMany({
      include: { translations: true },
    });

    const existingByKey = new Map<string, ExistingCategoryRecord>();
    const existingById = new Map<string, ExistingCategoryRecord>();

    for (const cat of categories) {
      const rec = cat as ExistingCategoryRecord;
      existingById.set(cat.id, rec);
      if (cat.importKey) {
        existingByKey.set(cat.importKey.toLowerCase(), rec);
      }
      existingByKey.set(`code:${cat.code.toLowerCase()}`, rec);
      existingByKey.set(`name:${cat.nameVi.trim().toLowerCase()}`, rec);
    }

    return {
      existingByKey,
      existingById,
      allExisting: categories as ExistingCategoryRecord[],
    };
  }

  diff(
    payload: MarketplaceCategoryImportPayload,
    state: MarketplaceCategoryImportState,
    _context: ImportContext,
    mode: ImportMode,
  ): ImportDiffEntry[] {
    if (mode !== "upsert" && mode !== "replace") {
      throw new Error(`Mode ${mode} is not supported by MarketplaceCategoryImportAdapter`);
    }

    const diffs: ImportDiffEntry[] = [];
    const matchedCategoryIds = new Set<string>();

    for (const row of payload.categories) {
      const key = row.importKey ? row.importKey.toLowerCase() : "";
      const codeKey = row.importKey ? `code:${row.importKey.toLowerCase()}` : "";
      const nameKey = row.nameVi ? `name:${row.nameVi.trim().toLowerCase()}` : "";

      const existing =
        (key ? state.existingByKey.get(key) : undefined) ??
        (codeKey ? state.existingByKey.get(codeKey) : undefined) ??
        (nameKey ? state.existingByKey.get(nameKey) : undefined);

      if (!existing) {
        const changes: ImportFieldChange[] = [
          { field: "nameVi", from: null, to: row.nameVi },
          { field: "sortOrder", from: null, to: row.sortOrder },
          { field: "isActive", from: null, to: row.isActive },
        ];
        for (const [loc, val] of Object.entries(row.translations)) {
          if (val) {
            changes.push({ field: `translation_${loc}`, from: null, to: val });
          }
        }
        diffs.push({
          entityType: "MarketplaceCategory",
          key: row.importKey,
          action: "create",
          label: row.nameVi,
          changes,
        });
      } else {
        matchedCategoryIds.add(existing.id);
        const changes: ImportFieldChange[] = [];

        if (existing.nameVi !== row.nameVi) {
          changes.push({ field: "nameVi", from: existing.nameVi, to: row.nameVi });
        }
        if (existing.sortOrder !== row.sortOrder) {
          changes.push({ field: "sortOrder", from: existing.sortOrder, to: row.sortOrder });
        }
        if (existing.isActive !== row.isActive) {
          changes.push({ field: "isActive", from: existing.isActive, to: row.isActive });
        }

        for (const [loc, val] of Object.entries(row.translations)) {
          if (val) {
            const currentTr = existing.translations.find((t) => t.locale === loc)?.name ?? null;
            if (currentTr !== val) {
              changes.push({ field: `translation_${loc}`, from: currentTr, to: val });
            }
          }
        }

        diffs.push({
          entityType: "MarketplaceCategory",
          key: row.importKey || existing.importKey || existing.code,
          action: changes.length > 0 ? "update" : "unchanged",
          label: row.nameVi,
          changes,
        });
      }
    }

    if (mode === "replace") {
      for (const existing of state.allExisting) {
        if (!matchedCategoryIds.has(existing.id)) {
          diffs.push({
            entityType: "MarketplaceCategory",
            key: existing.importKey || existing.code,
            action: "disable",
            label: existing.nameVi,
            changes: [{ field: "isActive", from: existing.isActive, to: false }],
          });
        }
      }
    }

    return diffs;
  }

  private text(value: unknown): string {
    if (value == null) return "";
    if (typeof value === "string") return value.trim();
    if (typeof value === "number" || typeof value === "boolean" || typeof value === "bigint")
      return `${value}`.trim();
    return (JSON.stringify(value) ?? "").trim();
  }

  async commit(
    input: ImportCommitInput<MarketplaceCategoryImportPayload, MarketplaceCategoryImportState>,
  ): Promise<ImportCommitResult> {
    const { tx, payload, diff } = input;

    let createCount = 0;
    let updateCount = 0;
    let disableCount = 0;
    let unchangedCount = 0;

    const diffMap = new Map<string, ImportDiffEntry>();
    for (const d of diff) {
      diffMap.set(d.key.toLowerCase(), d);
    }

    for (const d of diff) {
      if (d.action === "unchanged") {
        unchangedCount++;
        continue;
      }

      if (d.action === "disable") {
        const existing = await tx.marketplaceCategory.findFirst({
          where: {
            OR: [{ importKey: d.key }, { code: d.key }],
          },
        });
        if (existing) {
          await tx.marketplaceService.deleteMany({
            where: { categoryId: existing.id },
          });
          await tx.marketplaceCategory.delete({
            where: { id: existing.id },
          });
          disableCount++;
        }
      }
    }

    for (const row of payload.categories) {
      const key = (row.importKey || "").toLowerCase();
      const d =
        (key ? diffMap.get(key) : undefined) ??
        diffMap.get(`code:${key}`) ??
        diffMap.get(`name:${row.nameVi.trim().toLowerCase()}`);

      if (!d || d.action === "unchanged" || d.action === "disable") {
        continue;
      }

      if (d.action === "create") {
        const code = await this.codes.generateEntityCode("MARKETPLACE_CATEGORY", tx);
        const created = await tx.marketplaceCategory.create({
          data: {
            code,
            importKey: row.importKey,
            nameVi: row.nameVi,
            sortOrder: row.sortOrder,
            isActive: row.isActive,
          },
        });

        for (const [loc, val] of Object.entries(row.translations)) {
          if (val) {
            await tx.marketplaceCategoryTranslation.upsert({
              where: {
                categoryId_locale: {
                  categoryId: created.id,
                  locale: loc,
                },
              },
              create: {
                categoryId: created.id,
                locale: loc,
                name: val,
              },
              update: {
                name: val,
              },
            });
          }
        }
        createCount++;
      } else if (d.action === "update") {
        const existing = await tx.marketplaceCategory.findFirst({
          where: {
            OR: [
              { importKey: row.importKey },
              { code: row.importKey },
              { nameVi: { equals: row.nameVi, mode: "insensitive" } },
            ],
          },
        });
        if (existing) {
          await tx.marketplaceCategory.update({
            where: { id: existing.id },
            data: {
              importKey: row.importKey,
              nameVi: row.nameVi,
              sortOrder: row.sortOrder,
              isActive: row.isActive,
            },
          });

          for (const [loc, val] of Object.entries(row.translations)) {
            if (val) {
              await tx.marketplaceCategoryTranslation.upsert({
                where: {
                  categoryId_locale: {
                    categoryId: existing.id,
                    locale: loc,
                  },
                },
                create: {
                  categoryId: existing.id,
                  locale: loc,
                  name: val,
                },
                update: {
                  name: val,
                },
              });
            }
          }
          updateCount++;
        }
      }
    }

    const totalEntities = createCount + updateCount + disableCount + unchangedCount;
    const summary = {
      create: createCount,
      update: updateCount,
      disable: disableCount,
      unchanged: unchangedCount,
      errors: 0,
      warnings: 0,
      totalEntities,
      byEntityType: {
        MarketplaceCategory: {
          create: createCount,
          update: updateCount,
          disable: disableCount,
          unchanged: unchangedCount,
        },
      },
    };

    return { summary };
  }
}

import { Injectable, OnModuleInit } from "@nestjs/common";
import { ImportRegistry } from "../../../../common/import/import.registry";
import type {
  ImportAdapter,
  ImportCommitInput,
  ImportCommitResult,
  ImportContext,
  ImportDiffEntry,
  ImportMode,
  ImportValidationIssue,
  ImportWorkbookSchema,
  ParsedImportWorkbook,
} from "../../../../common/import/import.types";
import { PrismaService } from "../../../../prisma/prisma.service";
import { CodesService } from "../../../codes/codes.service";

const MAX_ROWS = 2000;
const REQUIRED_HEADERS = [
  "name_vi",
  "unit_price",
  "preparation_minutes",
  "capacity",
  "fulfillment_method",
  "status",
] as const;
const FORBIDDEN_CATEGORY_HEADERS = new Set([
  "category",
  "category_id",
  "category_key",
  "danh mục",
  "mã danh mục",
]);

type Row = {
  rowNumber: number;
  itemKey: string;
  name: string;
  description: string | null;
  unitPrice: number;
  preparationMinutes: number;
  capacity: number | null;
  mode: "DELIVERY_TO_HOTEL" | "CUSTOMER_AT_SERVICE";
  status: "DRAFT" | "ACTIVE" | "DISABLED";
  translations: Record<string, { name: string; description: string | null }>;
};

type Payload = { items: Row[]; fileHash?: string };
type StateItem = Pick<
  PrismaMarketplaceService,
  | "id"
  | "importKey"
  | "name"
  | "description"
  | "unitPrice"
  | "waitingMinutes"
  | "capacityAvailable"
  | "mode"
  | "status"
>;
type State = { items: StateItem[]; categoryId: string | null; categoryActive: boolean };
type PrismaMarketplaceService = {
  id: string;
  importKey: string | null;
  name: string;
  description: string | null;
  unitPrice: unknown;
  waitingMinutes: number;
  capacityAvailable: number | null;
  mode: "DELIVERY_TO_HOTEL" | "CUSTOMER_AT_SERVICE";
  status: "DRAFT" | "ACTIVE" | "DISABLED";
};

@Injectable()
export class MarketplaceServiceItemImportAdapter
  implements ImportAdapter<Payload, State>, OnModuleInit
{
  readonly type = "marketplace-service-items";
  readonly supportedModes = ["upsert"] as const;

  constructor(
    private readonly prisma: PrismaService,
    private readonly codes: CodesService,
    private readonly registry: ImportRegistry,
  ) {}

  onModuleInit() {
    this.registry.register(this);
  }

  getSchema(): ImportWorkbookSchema {
    return {
      sheets: [
        {
          name: "items",
          required: true,
          maxRows: MAX_ROWS,
          columns: [
            {
              key: "item_key",
              header: "Mã dịch vụ (Hệ thống tự sinh - không chỉnh sửa)",
              type: "string",
              maxLength: 120,
            },
            {
              key: "name_vi",
              header: "Tên dịch vụ (Tiếng Việt)",
              required: true,
              type: "string",
              maxLength: 160,
            },
            {
              key: "description_vi",
              header: "Mô tả (Tiếng Việt)",
              type: "string",
              maxLength: 1000,
            },
            { key: "unit_price", header: "Giá", required: true, type: "number", min: 0 },
            {
              key: "preparation_minutes",
              header: "Thời gian chuẩn bị (phút)",
              required: true,
              type: "number",
              min: 0,
            },
            { key: "capacity", header: "Sức chứa", type: "number", min: 0 },
            {
              key: "fulfillment_method",
              header: "Hình thức phục vụ",
              required: true,
              type: "enum",
              enumValues: ["1 - Phục vụ tại địa điểm", "2 - Giao tận nơi"],
            },
            {
              key: "status",
              header: "Trạng thái",
              required: true,
              type: "enum",
              enumValues: ["1 - Hoạt động", "2 - Tạm ẩn"],
            },
            ...["en", "zh", "ko", "ru", "hi"].flatMap((locale) => [
              {
                key: `name_${locale}`,
                header: `Tên (${locale})`,
                type: "string" as const,
                maxLength: 160,
              },
              {
                key: `description_${locale}`,
                header: `Mô tả (${locale})`,
                type: "string" as const,
                maxLength: 1000,
              },
            ]),
          ],
        },
      ],
    };
  }

  authorize(context: ImportContext) {
    if (!context.actorUserId || !context.tenantId)
      throw new Error("service item import requires actorUserId and tenantId");
  }

  parse(workbook: ParsedImportWorkbook, _context?: ImportContext): Payload {
    const sheet =
      workbook.sheets.find((s) => s.name.toLowerCase() === "items") ?? workbook.sheets[0];
    if (!sheet) return { items: [], fileHash: workbook.fileHash };
    return {
      fileHash: workbook.fileHash,
      items: sheet.rows.map((row) => ({
        rowNumber: row.rowNumber,
        itemKey: this.text(row.values.item_key),
        name: this.text(row.values.name_vi),
        description: this.optional(row.values.description_vi),
        unitPrice: this.number(row.values.unit_price),
        preparationMinutes: this.number(row.values.preparation_minutes),
        capacity: this.optionalNumber(row.values.capacity),
        mode: this.mode(row.values.fulfillment_method),
        status: this.status(row.values.status),
        translations: Object.fromEntries(
          ["en", "zh", "ko", "ru", "hi"].flatMap((locale) => {
            const name = this.text(row.values[`name_${locale}`]);
            return name
              ? [
                  [
                    locale,
                    { name, description: this.optional(row.values[`description_${locale}`]) },
                  ],
                ]
              : [];
          }),
        ),
      })),
    };
  }

  validate(payload: Payload, _context?: ImportContext): ImportValidationIssue[] {
    const issues: ImportValidationIssue[] = [];
    const seen = new Map<string, number>();
    if (payload.items.length > MAX_ROWS)
      issues.push({
        severity: "error",
        sheet: "items",
        code: "MAX_ROWS_EXCEEDED",
        message: `Tối đa ${MAX_ROWS} dòng mỗi lần nhập`,
      });
    for (const row of payload.items) {
      const key = row.name.toLocaleLowerCase("vi");
      if (seen.has(key))
        this.error(
          issues,
          row,
          "name_vi",
          "DUPLICATE_NAME",
          `Trùng tên tiếng Việt với dòng ${seen.get(key)}`,
        );
      else if (key) seen.set(key, row.rowNumber);
      if (!row.name) this.error(issues, row, "name", "REQUIRED_FIELD_MISSING", "Thiếu tên dịch vụ");
      else if (row.name.length > 160)
        this.error(issues, row, "name", "MAX_LENGTH_EXCEEDED", "Tên dịch vụ tối đa 160 ký tự");
      if (row.description != null && row.description.length > 1000)
        this.error(issues, row, "description", "MAX_LENGTH_EXCEEDED", "Mô tả tối đa 1000 ký tự");
      if (!Number.isFinite(row.unitPrice) || row.unitPrice < 0 || row.unitPrice > 9999999999.99)
        this.error(
          issues,
          row,
          "unit_price",
          "INVALID_NUMBER",
          "Giá phải là số từ 0 đến 9999999999.99",
        );
      else if (!/^\d+(?:\.\d{1,2})?$/.test(String(row.unitPrice)))
        this.error(
          issues,
          row,
          "unit_price",
          "INVALID_PRICE_SCALE",
          "Giá tối đa 2 chữ số thập phân",
        );
      if (!Number.isInteger(row.preparationMinutes) || row.preparationMinutes < 0)
        this.error(
          issues,
          row,
          "preparation_minutes",
          "INVALID_NUMBER",
          "Thời gian chuẩn bị phải là số nguyên >= 0",
        );
      if (row.capacity != null && (!Number.isInteger(row.capacity) || row.capacity < 0))
        this.error(issues, row, "capacity", "INVALID_NUMBER", "Sức chứa phải là số nguyên >= 0");
      if (!["DELIVERY_TO_HOTEL", "CUSTOMER_AT_SERVICE"].includes(row.mode))
        this.error(
          issues,
          row,
          "fulfillment_method",
          "INVALID_ENUM",
          "Hình thức phục vụ không hợp lệ",
        );
      if (!["DRAFT", "ACTIVE", "DISABLED"].includes(row.status))
        this.error(issues, row, "status", "INVALID_ENUM", "Trạng thái không hợp lệ");
    }
    return issues;
  }

  async loadCurrentState(
    context: ImportContext,
    db: Pick<PrismaService, "serviceTenantProfile" | "marketplaceService"> = this.prisma,
  ): Promise<State> {
    const tenantId = String(context.tenantId);
    const [profile, items] = await Promise.all([
      db.serviceTenantProfile.findUnique({
        where: { tenantId },
        select: { categoryId: true, category: { select: { isActive: true } } },
      }),
      db.marketplaceService.findMany({
        where: { serviceTenantId: tenantId, importKey: { not: null } },
        orderBy: { id: "asc" },
        select: {
          id: true,
          importKey: true,
          name: true,
          description: true,
          unitPrice: true,
          waitingMinutes: true,
          capacityAvailable: true,
          mode: true,
          status: true,
        },
      }),
    ]);
    return {
      categoryId: profile?.categoryId ?? null,
      categoryActive: profile?.category?.isActive === true,
      items: items,
    };
  }

  diff(
    payload: Payload,
    state: State,
    _context: ImportContext,
    _mode: ImportMode,
  ): ImportDiffEntry[] {
    const byCode = new Map(
      state.items
        .filter((item): item is StateItem & { importKey: string } => Boolean(item.importKey))
        .map((item) => [item.importKey.toLowerCase(), item]),
    );
    const byName = new Map(state.items.map((item) => [item.name.toLocaleLowerCase("vi"), item]));
    return payload.items.map((row) => {
      const current = row.itemKey
        ? byCode.get(row.itemKey.toLowerCase())
        : byName.get(row.name.toLocaleLowerCase("vi"));
      if (!current)
        return {
          entityType: "MarketplaceService",
          key: row.name,
          action: "create",
          label: row.name,
          changes: [],
        };
      const changes = this.changes(current, row);
      return {
        entityType: "MarketplaceService",
        key: current.importKey ?? current.id,
        action: changes.length ? "update" : "unchanged",
        label: row.name,
        changes,
      };
    });
  }

  async commit(input: ImportCommitInput<Payload, State>): Promise<ImportCommitResult> {
    const tenantId = String(input.context.tenantId);
    if (!input.currentState.categoryId || !input.currentState.categoryActive)
      throw new Error("Service Tenant chưa được gán danh mục hoạt động");
    const byCode = new Map(
      input.currentState.items
        .filter((item): item is StateItem & { importKey: string } => Boolean(item.importKey))
        .map((item) => [item.importKey.toLowerCase(), item]),
    );
    const byName = new Map(
      input.currentState.items.map((item) => [item.name.toLocaleLowerCase("vi"), item]),
    );
    const generatedCodes: Array<{ rowNumber: number; code: string }> = [];
    let create = 0,
      update = 0,
      unchanged = 0;
    const batchSize = 250;
    for (let offset = 0; offset < input.payload.items.length; offset += batchSize) {
      const batch = input.payload.items.slice(offset, offset + batchSize);
      const creates = batch.filter(
        (row) => !row.itemKey && !byName.has(row.name.toLocaleLowerCase("vi")),
      );
      for (const row of creates) {
        const importKey = await this.codes.generateEntityCode("MARKETPLACE_SERVICE", input.tx);
        const created = await input.tx.marketplaceService.create({
          data: {
            serviceTenantId: tenantId,
            importKey,
            categoryId: input.currentState.categoryId,
            name: row.name,
            description: row.description,
            unitPrice: row.unitPrice,
            currency: "VND",
            imageUrls: [],
            mode: row.mode,
            capacityAvailable: row.capacity,
            waitingMinutes: row.preparationMinutes,
            status: row.status,
          },
        });
        await this.upsertTranslations(input.tx, created.id, row.translations);
        generatedCodes.push({ rowNumber: row.rowNumber, code: importKey });
        create++;
      }
      for (const row of batch) {
        const current = row.itemKey
          ? byCode.get(row.itemKey.toLowerCase())
          : byName.get(row.name.toLocaleLowerCase("vi"));
        if (current) {
          if (!row.itemKey && current.importKey)
            generatedCodes.push({ rowNumber: row.rowNumber, code: current.importKey });
          const changes = this.changes(current, row);
          if (!changes.length) {
            unchanged++;
            continue;
          }
          const result = await input.tx.marketplaceService.updateMany({
            where: { id: current.id, serviceTenantId: tenantId },
            data: {
              name: row.name,
              description: row.description,
              unitPrice: row.unitPrice,
              mode: row.mode,
              capacityAvailable: row.capacity,
              waitingMinutes: row.preparationMinutes,
              status: row.status,
              categoryId: input.currentState.categoryId,
              version: { increment: 1 },
            },
          });
          if (result.count !== 1) throw new Error("Service item changed during import");
          await this.upsertTranslations(input.tx, current.id, row.translations);
          update++;
        }
      }
    }
    return {
      summary: {
        create,
        update,
        disable: 0,
        unchanged,
        errors: 0,
        warnings: 0,
        totalEntities: input.payload.items.length,
        byEntityType: { MarketplaceService: { create, update, disable: 0, unchanged } },
      },
      auditPayload: { generatedCodes },
    };
  }

  validateState(payload: Payload, state: State): ImportValidationIssue[] {
    const codes = new Set(
      state.items
        .map((item) => item.importKey?.toLowerCase())
        .filter((k): k is string => Boolean(k)),
    );
    return payload.items.flatMap((row) =>
      row.itemKey && !codes.has(row.itemKey.toLowerCase())
        ? [
            {
              severity: "error" as const,
              sheet: "items",
              row: row.rowNumber,
              column: "item_key",
              code: "SERVICE_CODE_NOT_FOUND",
              message: `Mã dịch vụ không tồn tại: ${row.itemKey}`,
            },
          ]
        : [],
    );
  }

  private changes(current: StateItem, row: Row) {
    const fields: Array<[string, unknown, unknown]> = [
      ["name", current.name, row.name],
      ["description", current.description, row.description],
      ["unitPrice", String(current.unitPrice), row.unitPrice.toFixed(2)],
      ["waitingMinutes", current.waitingMinutes, row.preparationMinutes],
      ["capacityAvailable", current.capacityAvailable, row.capacity],
      ["mode", current.mode, row.mode],
      ["status", current.status, row.status],
    ];
    return fields
      .filter(([, from, to]) => this.text(from) !== this.text(to))
      .map(([field, from, to]) => ({ field, from: this.text(from), to: this.text(to) }));
  }

  private async upsertTranslations(
    tx: ImportCommitInput<Payload, State>["tx"],
    serviceId: string,
    translations: Row["translations"],
  ) {
    if (!translations) return;
    for (const [locale, value] of Object.entries(translations)) {
      if (!value || (!value.name && !value.description)) continue;
      await tx.marketplaceServiceTranslation.upsert({
        where: { serviceId_locale: { serviceId, locale } },
        create: {
          serviceId,
          locale,
          name: value.name || "",
          description: value.description ?? null,
        },
        update: { name: value.name || "", description: value.description ?? null },
      });
    }
  }

  private error(
    issues: ImportValidationIssue[],
    row: Row,
    column: string,
    code: string,
    message: string,
  ) {
    issues.push({ severity: "error", sheet: "items", row: row.rowNumber, column, code, message });
  }
  private text(value: unknown) {
    if (value == null) return "";
    if (typeof value === "string") return value.trim();
    if (typeof value === "number" || typeof value === "boolean" || typeof value === "bigint")
      return `${value}`.trim();
    return (JSON.stringify(value) ?? "").trim();
  }
  private optional(value: unknown) {
    const v = this.text(value);
    return v || null;
  }
  private number(value: unknown) {
    const v = this.text(value);
    return v === "" ? Number.NaN : Number(v);
  }
  private optionalNumber(value: unknown) {
    const v = this.text(value);
    return v === "" ? null : Number(v);
  }
  private enum(value: unknown) {
    return this.text(value).toUpperCase();
  }
  private mode(value: unknown): Row["mode"] {
    const v = this.enum(value);
    if (["1", "1 - PHỤC VỤ TẠI ĐỊA ĐIỂM", "CUSTOMER_AT_SERVICE"].includes(v))
      return "CUSTOMER_AT_SERVICE";
    if (["2", "2 - GIAO TẬN NƠI", "DELIVERY_TO_HOTEL"].includes(v)) return "DELIVERY_TO_HOTEL";
    return v as Row["mode"];
  }
  private status(value: unknown): Row["status"] {
    const v = this.enum(value);
    if (["1", "1 - HOẠT ĐỘNG", "ACTIVE"].includes(v)) return "ACTIVE";
    if (["2", "2 - TẠM ẨN", "DISABLED"].includes(v)) return "DISABLED";
    return v as Row["status"];
  }
}

